enum class CandidateKind {
    
    ROAD,
    BUILDING,
    BUSINESS;
    companion object
}


/**
 * @suppress
 */
public object FfiConverterTypeCandidateKind: FfiConverterRustBuffer<CandidateKind> {
    override fun read(buf: ByteBuffer) = try {
        CandidateKind.values()[buf.getInt() - 1]
    } catch (e: IndexOutOfBoundsException) {
        throw RuntimeException("invalid enum value, something is very wrong!!", e)
    }

    override fun allocationSize(value: CandidateKind) = 4UL

    override fun write(value: CandidateKind, buf: ByteBuffer) {
        buf.putInt(value.ordinal + 1)
    }
}







/**
 * Flat UniFFI error enum. Every error path anywhere in this crate collapses
 * into one of these variants; wrapped source errors are stringified
 * (`{0}`/`{message}`) rather than exposed as nested UniFFI error types,
 * which keeps the generated Swift/Kotlin error surface small and stable.
 */
sealed class PtilesException(message: String): kotlin.Exception(message) {
        
        class Open(message: String) : PtilesException(message)
        
        class UnknownLayer(message: String) : PtilesException(message)
        
        class Decode(message: String) : PtilesException(message)
        
        class UnsupportedForLayer(message: String) : PtilesException(message)
        
        class InvalidRing(message: String) : PtilesException(message)
        

    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<PtilesException> {
        override fun lift(error_buf: RustBuffer.ByValue): PtilesException = FfiConverterTypePtilesError.lift(error_buf)
    }
}

/**
 * @suppress
 */
public object FfiConverterTypePtilesError : FfiConverterRustBuffer<PtilesException> {
    override fun read(buf: ByteBuffer): PtilesException {
        
            return when(buf.getInt()) {
            1 -> PtilesException.Open(FfiConverterString.read(buf))
            2 -> PtilesException.UnknownLayer(FfiConverterString.read(buf))
            3 -> PtilesException.Decode(FfiConverterString.read(buf))
            4 -> PtilesException.UnsupportedForLayer(FfiConverterString.read(buf))
            5 -> PtilesException.InvalidRing(FfiConverterString.read(buf))
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
        
    }

    override fun allocationSize(value: PtilesException): ULong {
        return 4UL
    }

    override fun write(value: PtilesException, buf: ByteBuffer) {
        when(value) {
            is PtilesException.Open -> {
                buf.putInt(1)
                Unit
            }
            is PtilesException.UnknownLayer -> {
                buf.putInt(2)
                Unit
            }
            is PtilesException.Decode -> {
                buf.putInt(3)
                Unit
            }
            is PtilesException.UnsupportedForLayer -> {
                buf.putInt(4)
                Unit
            }
            is PtilesException.InvalidRing -> {
                buf.putInt(5)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}




/**
